  function insideCircle(p, c) {
    const dx = p.x - c.cx;
    const dy = p.y - c.cy;
    return dx * dx + dy * dy &lt;= c.r * c.r;
  }

  function regionOf(p) {
    const inA = insideCircle(p, left);
    const inB = insideCircle(p, right);
    if (inA && inB) return "both";
    if (inA) return "A";
    if (inB) return "B";
    return "outside";
  }

  function resultIncludes(region, operation) {
    if (operation === "union") return region !== "outside";
    if (operation === "intersection") return region === "both";
    if (operation === "adiffb") return region === "A";
    if (operation === "bdiffa") return region === "B";
    if (operation === "acomplement") return region !== "A" && region !== "both";
    if (operation === "symdiff") return region === "A" || region === "B";
    if (operation === "implication") return region !== "A";
    return false;
  }

  function chips(values) {
    if (values.length === 0) return "∅";
    return values.map(v =&gt; `&lt;span class="chip"&gt;${v}&lt;/span&gt;`).join("");
  }

  function boundsClamp(x, y) {
    return {
      x: Math.max(universe.x + 10, Math.min(universe.x + universe.w - 10, x)),
      y: Math.max(universe.y + 10, Math.min(height - 18, y))
    };
  }

  function clearPresetSelection() {
