    const targets = [
      {x: 202, y: 126}, {x: 204, y: 232}, {x: 270, y: 267},
      {x: 477, y: 128}, {x: 475, y: 235},
      {x: 340, y: 132}, {x: 340, y: 228},
      {x: 104, y: 278}
    ];
    for (let i = targets.length - 1; i &gt; 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [targets[i], targets[j]] = [targets[j], targets[i]];
    }
    state.points.forEach((p, i) =&gt; {
