    for (let order = 1; order &lt;= n; order++) {
      const row = document.createElement("div");
      row.className = "count-row";
      panel.appendChild(row);

      function addTerm(indices, next) {
        if (indices.length === order) {
          const name = indices.map(i =&gt; labels[i]).join(" ∩ ");
          const cell = document.createElement("span");
          const value = document.createTextNode("");
          cell.append(`|${name}| = `, value);
          row.appendChild(cell);
          terms.push({indices, value});
          return;
        }

        const last = n - (order - indices.length);
        for (let i = next; i &lt;= last; i++) {
          addTerm([...indices,i], i+1);
        }
      }

      addTerm([],0);
    }

    update();
  }

  function update() {
    const memberships = points.map((p,i) =&gt; {
      const inside = circles.map(c =&gt; Math.hypot(p.x-c.x, p.y-c.y) &lt;= c.r);
      const members = circles.filter((_,j) =&gt; inside[j]).map(c =&gt; c.label);
      const dot = dots[i];

      dot.setAttribute("transform", `translate(${p.x},${p.y})`);
      dot.setAttribute("aria-label", `Dot ${i+1}: ${members.join(", ") || "outside all sets"}`);

      let fill = "#89939a";
      if (members.length === 1) fill = colors[inside.indexOf(true)];
      if (members.length &gt; 1) fill = "#635080";
      dot.querySelector("[data-core]").setAttribute("fill", fill);

      return inside;
    });

    for (const {indices,value} of terms) {
      value.data = String(memberships.filter(inside =&gt; indices.every(j =&gt; inside[j])).length);
    }

    const union = memberships.filter(inside =&gt; inside.some(Boolean)).length;
    get(".union").textContent = `|${circles.map(c =&gt; c.label).join(" ∪ ")}| = ${union}`;
  }

  function move(i,x,y) {
    // Keep the dots inside Ω and leave the bottom strip clear for the key.
    points[i] = {
      x: Math.max(158, Math.min(442,x)),
      y: Math.max(21, Math.min(286,y))
    };
    update();
  }

  function pointerPosition(event) {
    const point = new DOMPoint(event.clientX,event.clientY);
    return point.matrixTransform(svg.getScreenCTM().inverse());
  }

  const directions = {
    ArrowLeft: [-1,0], ArrowRight: [1,0],
    ArrowUp: [0,-1], ArrowDown: [0,1]
  };

  dots.forEach((dot,i) =&gt; {
    dot.onpointerdown = event =&gt; {
      if (drag || event.button !== 0) return;
      const p = pointerPosition(event);
      drag = {i, id:event.pointerId, dx:points[i].x-p.x, dy:points[i].y-p.y};
      dot.setPointerCapture(event.pointerId);
      dot.focus();
    };

    dot.onpointermove = event =&gt; {
      if (!drag || drag.i !== i || drag.id !== event.pointerId) return;
      const p = pointerPosition(event);
      move(i,p.x+drag.dx,p.y+drag.dy);
    };

    dot.onlostpointercapture = event =&gt; {
      if (drag && drag.id === event.pointerId) drag = null;
    };

    dot.onkeydown = event =&gt; {
      const d = directions[event.key];
      if (!d) return;
      event.preventDefault();
      move(i,points[i].x+5*d[0],points[i].y+5*d[1]);
    };
  });

  get("[data-n]").onchange = configure;
  get("[data-reset]").onclick = () =&gt; {
    points = initial.map(([x,y]) =&gt; ({x,y}));
    update();
  };

  configure();
  return widget;
}

The martingale transform allows us to use the ,


Note that \(M^{(n)}(\tau)\) is often an average of individual martingales, \[\begin{aligned}
M^{(n)}(\tau)
  &= \frac{1}{n}\sum_{i=1}^n M_i(\tau)
   = \frac{1}{n} M(\tau),\\[4pt]
\langle M^{(n)}\rangle(\tau)
  &= \frac{1}{n^2}\sum_{i=1}^n \langle M_i\rangle(\tau)
   = \frac{1}{n^2}\langle M\rangle(\tau),
\end{aligned}\] Thus, at any fixed \(\tau\), \[\frac{M^{(n)}(\tau)}{\sqrt{\langle M^{(n)}\rangle(\tau)}}
  = \frac{M(\tau)/n}{\sqrt{\langle M\rangle(\tau)/n^2}}
  = \frac{M(\tau)}{\sqrt{\langle M\rangle(\tau)}}\]
Under the conditions of the martingale CLT (and using Slutsky’s theorem for plug-in estimation of the bracket), we obtain \[\frac{M^{(n)}(\tau)}{\sqrt{\langle M^{(n)}\rangle(\tau)}}
  = \frac{M(\tau)}{\sqrt{\langle M\rangle(\tau)}}
  \xrightarrow{d} N(0,1)\] exactly analogous to the classical CLT for the sample mean. In what follows we may omit the superscript \((n)\) when no confusion arises.

We now have all the building blocks we need to understand nonparametric survival straigthforwardly,

