What counts as a different outcome?



Our answers depend on whether we care about the sequence in which we choose items (order) and whether we can choose the same item more than once (replacement). Order and replacement determine which of the four counting rules below applies when selecting \(m\) items from \(n\) distinct items.












With Replacement
Without Replacement




Order Matters
\(n^m\)
\(\displaystyle \frac{n!}{(n-m)!}\)


Order Does Not Matter
\(\displaystyle \binom{n-1+m}{m}=\frac{(n-1+m)!}{(n-1)!m!}\)
\(\displaystyle \binom{n}{m}=\frac{n!}{m!(n-m)!}\)





countingModel = {
  const changes = new EventTarget();
  const letters = "ABCDEFGHIJKLMNOPQRST";
  let n = 3;
  let m = 2;

  function set(nextN, nextM) {
    if (nextN === n && nextM === m) return;
    n = nextN;
    m = nextM;
    changes.dispatchEvent(new Event("change"));
  }

  function populate(select, min, initial) {
    for (let i = min; i &lt;= 20; i++) select.add(new Option(i, i));
    select.value = initial;
  }

  // BigInt keeps counts and page positions exact, even for 20^20.
  function choose(n, k) {
    if (k &lt; 0 || k &gt; n) return 0n;
    k = Math.min(k, n - k);
    let result = 1n;
    for (let i = 1; i &lt;= k; i++) {
      result = result * BigInt(n - i + 1) / BigInt(i);
    }
    return result;
  }

  function ways(n, m, ordered, repeats) {
    if (m === 0) return 1n;
    if (n === 0 || (!repeats && m &gt; n)) return 0n;
    if (!ordered) return choose(repeats ? n + m - 1 : n, m);
    if (repeats) return BigInt(n) ** BigInt(m);
    let result = 1n;
    for (let i = 0; i &lt; m; i++) result *= BigInt(n - i);
    return result;
  }

  const style = `
    .count-demo {
      color:#35424d; background:#fbfcfd; border:1px solid #d5dce1;
      border-left:4px solid #79658e; border-radius:.5rem;
