    .count-demo p { margin:.45rem 0; }
    .count-demo .controls, .count-demo .bins, .count-demo .outcomes,
    .count-demo .pager {
      display:flex; flex-wrap:wrap; align-items:center;
      gap:.45rem .8rem; margin:.7rem 0;
    }
    .count-demo button, .count-demo select {
      font:inherit; color:inherit; background:white;
      border:1px solid #bbc5cd; border-radius:.35rem; padding:.2rem .5rem;
    }
    .count-demo button:enabled { cursor:pointer; }
    .count-demo button:disabled { opacity:.55; }
    .count-demo :focus-visible { outline:2px solid #506c83; outline-offset:2px; }
    .count-demo .bin { min-width:4.6rem; min-height:4rem; text-align:center; }
    .count-demo .bin[aria-pressed="true"] { outline:2px solid #635080; }
    .count-demo .stars {
      display:block; color:#635080; max-width:9rem; overflow-wrap:anywhere;
    }
    .count-demo .outcomes { gap:.35rem; }
    .count-demo .chip {
      background:#ede9f3; color:#49395e; border-radius:.3rem;
      padding:.2rem .5rem; font-family:monospace;
    }
    .count-demo .answer { font-weight:700; }
    .count-demo [hidden] { display:none; }
  `;

  return {
    get n() { return n; }, get m() { return m; },
    set, changes, letters, populate, ways, style,
    format: value =&gt; value.toLocaleString("en-US")
  };
}







