  // Skip whole groups of outcomes sharing a prefix to reach the requested rank.
  function outcomeAt(rank, items, draws, ordered, repeats) {
    let available = items;
    let outcome = "";
    for (let left = draws; left &gt; 0; left--) {
      for (let i = 0; i &lt; available.length; i++) {
        let next;
        if (ordered) {
          next = repeats ? available : available.slice(0, i) + available.slice(i + 1);
        } else {
          next = available.slice(repeats ? i : i + 1);
        }
        const block = model.ways(next.length, left - 1, ordered, repeats);
        if (rank &lt; block) {
          outcome += available[i];
          available = next;
          break;
