  }
  function pairList(){
    const unconditioned=state.nodes.filter(n=&gt;!state.z.includes(n.id));
    const pairs=[];
    for(let i=0;i&lt;unconditioned.length;i++)for(let j=i+1;j&lt;unconditioned.length;j++){
      const a=unconditioned[i].id,b=unconditioned[j].id;
